mapper.select:
SELECT b.post_id AS postId, b.title AS title, b.content AS content, b.created_date AS createdDate, b.view_count AS viewCount, b.deleted AS deleted, b.category_id AS categoryId, b.writer_id AS writerId, b.sub_category AS subCategory, b.image_name AS imageName, b.video_url AS videoUrl, b.end_date AS endDate, u.nickname AS writerName, u.member_type AS memberType, u.grade_id AS gradeId, u.activity_point AS activityPoint, u.profile AS writerProfile, c.category_name AS categoryName, (SELECT COUNT(*) FROM board_like bl WHERE bl.post_id = b.post_id) AS likeCount, (SELECT COUNT(*) FROM board_reply br WHERE br.post_id = b.post_id) AS replyCount, ( SELECT COUNT(*) FROM board_reply r JOIN user ru ON r.writer_id = ru.member_id WHERE r.post_id = b.post_id AND ru.member_type = '관리자' ) AS adminReplyCount FROM board b LEFT JOIN user u ON b.writer_id = u.member_id LEFT JOIN category c ON b.category_id = c.category_id
b.deleted = 0
AND b.writer_id = #{writerId}
AND b.category_id = #{categoryId}
AND b.sub_category = #{subCategory}
AND ( b.title LIKE CONCAT('%', #{keyword}, '%') OR b.content LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY CASE WHEN b.category_id = 1 THEN 0 ELSE 1 END ASC,
b.created_date ASC b.created_date DESC b.view_count ASC b.view_count DESC likeCount ASC likeCount DESC b.post_id DESC
LIMIT #{size} OFFSET #{startRow}

SELECT COUNT(*)
FROM board

	deleted = 0

		AND writer_id = #{writerId}


		AND category_id = #{categoryId}


		AND sub_category = #{subCategory}


		AND (
		title LIKE CONCAT('%', #{keyword}, '%')
		OR content
		LIKE CONCAT('%', #{keyword}, '%')
		)

